from uuid import uuid4


class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        # Insertion-ordered dict: job_id -> record. Dicts preserve insertion
        # order (Python 3.7+), so scanning it yields IDs in insertion order.
        self._jobs = {}

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {
                    'state': 'queued',
                    'worker': None,
                    'token': None,
                    'expiry': None,
                    'completed': False,
                }

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        with self._lock:
            for job_id, rec in self._jobs.items():
                if rec['completed']:
                    continue
                if rec['state'] == 'queued':
                    rec['state'] = 'running'
                    rec['worker'] = worker
                    rec['token'] = uuid4().hex
                    rec['expiry'] = now + ttl
                    return {'job_id': job_id, 'worker': worker,
                            'token': rec['token']}
                if rec['state'] == 'running' and rec['expiry'] <= now:
                    # Expired lease: reclaimable; new worker gets a NEW token.
                    rec['state'] = 'running'
                    rec['worker'] = worker
                    rec['token'] = uuid4().hex
                    rec['expiry'] = now + ttl
                    return {'job_id': job_id, 'worker': worker,
                            'token': rec['token']}
            return None

    def _find_valid_lease(self, lease, now):
        """Return the job record if the exact current lease is valid, else None."""
        with self._lock:
            rec = self._jobs.get(lease['job_id'])
            if (rec is None or rec['completed'] or rec['state'] != 'running'
                    or rec['token'] != lease['token']
                    or rec['worker'] != lease['worker']
                    or rec['expiry'] <= now):
                return None
            return rec

    def renew(self, lease, now, ttl):
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        rec = self._find_valid_lease(lease, now)
        if rec is None:
            return False
        with self._lock:
            rec['expiry'] = now + ttl
        return True

    def complete(self, lease, now):
        rec = self._find_valid_lease(lease, now)
        if rec is None:
            return False
        with self._lock:
            rec['state'] = 'completed'
            rec['completed'] = True
        return True
